once('''                bool useGridForThisTrade = EnableFibGrid; // v28 Fibonacci Grid core module\n                _pendingPrimaryUseGrid = useGridForThisTrade;\n\n                if (useGridForThisTrade)\n                {\n                    orderSlPips = slPips * GridStopFib;\n                    orderTpPips = null;\n                    _lastPrimaryRiskPips = slPips;\n                    volumeInUnits = CalculateVolumeByRisk(orderSlPips, riskBudgetPct);\n                }\n                else\n                {\n                    _lastPrimaryRiskPips = 0;\n                    volumeInUnits = CalculateVolumeByRisk(slPips, riskBudgetPct);\n                    if (false) // removed legacy helper; presets control Grid availability\n                        Print("[GRID-GUARD] Small account mode: primary trade uses normal SL/TP; grid disabled for this position.");\n                }\n\n                if (volumeInUnits <= 0)\n                {\n                    _diagVolumeBlocked++;\n                    _pendingPrimaryUseGrid = false;\n                    return;\n                }''','''                bool useGridForThisTrade = EnableFibGrid; // Fibonacci Grid remains a core module\n                double absoluteRiskCapPct = CommercialRiskEngine ? Math.Max(0.0, RiskPercent) : Math.Max(0.0, riskBudgetPct);\n\n                if (useGridForThisTrade)\n                {\n                    double candidateGridStopPips = slPips * GridStopFib;\n                    double gridPrimaryMinRiskPct = EstimateMinVolumeRiskPercent(candidateGridStopPips);\n                    if (CommercialRiskEngine && CapitalAwareGridFallback && gridPrimaryMinRiskPct > absoluteRiskCapPct + FinalRiskTolerancePercent)\n                    {\n                        useGridForThisTrade = false;\n                        _v284GridPrimaryFallback++;\n                        V282AuditGrid(signal.PatternName, "primary-capital-fallback", absoluteRiskCapPct);\n                        Print("[V284-GRID-FALLBACK] pattern={0} gridStop={1:F1} minVolAllInRisk={2:F3}% > absoluteCap={3:F3}%; primary keeps normal SL/TP, Grid stays enabled for feasible trades.",\n                            signal.PatternName, candidateGridStopPips, gridPrimaryMinRiskPct, absoluteRiskCapPct);\n                    }\n                }\n\n                _pendingPrimaryUseGrid = useGridForThisTrade;\n                if (useGridForThisTrade)\n                {\n                    orderSlPips = slPips * GridStopFib;\n                    orderTpPips = null;\n                    _lastPrimaryRiskPips = slPips;\n                    volumeInUnits = CalculateVolumeByRisk(orderSlPips, riskBudgetPct);\n                    if (volumeInUnits > 0) V282AuditGrid(signal.PatternName, "primary-grid-active", GetEffectiveGridRiskCapPercent());\n                }\n                else\n                {\n                    _lastPrimaryRiskPips = 0;\n                    volumeInUnits = CalculateVolumeByRisk(slPips, riskBudgetPct);\n                }\n\n                if (volumeInUnits <= 0)\n                {\n                    _diagVolumeBlocked++;\n                    _pendingPrimaryUseGrid = false;\n                    return;\n                }\n\n                double finalRiskPct = EstimateVolumeRiskPercent(volumeInUnits, orderSlPips);\n                if (CommercialRiskEngine && finalRiskPct > absoluteRiskCapPct + FinalRiskTolerancePercent)\n                {\n                    _v284FinalRiskBlocked++;\n                    _diagVolumeBlocked++;\n                    _pendingPrimaryUseGrid = false;\n                    Print("[V284-FINAL-RISK-BLOCK] pattern={0} vol={1} stop={2:F1} allInRisk={3:F3}% > cap={4:F3}%",\n                        signal.PatternName, volumeInUnits, orderSlPips, finalRiskPct, absoluteRiskCapPct);\n                    return;\n                }''','capital aware grid + final risk')

