helpers='''        private double EstimateVolumeRiskPercent(double volumeInUnits, double slPips)\n        {\n            if (_symbol == null || Account.Equity <= 0 || volumeInUnits <= 0 || slPips <= 0) return double.MaxValue;\n            try\n            {\n                double allIn = slPips + (CommercialRiskEngine ? EstimateExecutionReservePips() : 0.0);\n                double money = _symbol.AmountRisked(volumeInUnits, allIn);\n                return 100.0 * money / Account.Equity;\n            }\n            catch { return double.MaxValue; }\n        }\n\n        private bool PassPrzReversalConfirmation(Signal signal, int signalIndex, double atrNow)\n        {\n            if (!PrzReversalConfirmation) return true;\n            if (signal == null || _signalBars == null || atrNow <= 0) return false;\n            int i = Math.Min(signalIndex, _signalBars.Count - 2);\n            if (i < 1) return false;\n\n            double o = _signalBars.OpenPrices[i];\n            double h = _signalBars.HighPrices[i];\n            double l = _signalBars.LowPrices[i];\n            double c = _signalBars.ClosePrices[i];\n            double range = Math.Max(h - l, _symbol != null ? _symbol.TickSize : 0.0000001);\n            double bodyAtr = Math.Abs(c - o) / atrNow;\n            double closeLoc = signal.Direction == TradeDirection.Buy ? (c - l) / range : (h - c) / range;\n            bool directionalBody = signal.Direction == TradeDirection.Buy ? c > o : c < o;\n            bool followThrough = signal.Direction == TradeDirection.Buy ? c >= _signalBars.ClosePrices[i - 1] : c <= _signalBars.ClosePrices[i - 1];\n            return directionalBody && followThrough && bodyAtr + 1e-9 >= ConfirmMinBodyAtr && closeLoc + 1e-9 >= ConfirmCloseLocation;\n        }\n\n'''
s=s.replace(anchor,helpers+anchor,1)

once('''            if (vol >= _symbol.VolumeInUnitsMin)\n                return (CheckNotionalLimit(vol) && CheckMarginLimit(vol)) ? vol : 0;''','''            if (vol >= _symbol.VolumeInUnitsMin)\n            {\n                double actualRiskPct = EstimateVolumeRiskPercent(vol, slPips);\n                double absoluteCapPct = CommercialRiskEngine ? Math.Max(0.0, RiskPercent) : Math.Max(0.0, pct);\n                if (CommercialRiskEngine && actualRiskPct > absoluteCapPct + FinalRiskTolerancePercent)\n                {\n                    _v284FinalRiskBlocked++;\n                    if ((Server.Time - _lastVolumeWarnTime).TotalMinutes >= 5)\n                    {\n                        Print("[V284-VOLUME-RISK-BLOCK] normalizedVol={0} allInRisk={1:F3}% > absoluteCap={2:F3}%.", vol, actualRiskPct, absoluteCapPct);\n                        _lastVolumeWarnTime = Server.Time;\n                    }\n                    return 0;\n                }\n                return (CheckNotionalLimit(vol) && CheckMarginLimit(vol)) ? vol : 0;\n            }''','normalized volume risk recheck')

